BEGIN;
SELECT set_config('htt.company_id','00000000-0000-0000-0000-000000000001',true),set_config('htt.actor_id','00000000-0000-0000-0000-000000000002',true),set_config('htt.request_id','synthetic-improvements',true);
SAVEPOINT before_variance;
DO $$ DECLARE b uuid;v numeric;BEGIN
 SELECT id INTO b FROM inventory.stock_balances WHERE company_id=core.current_company() AND warehouse_id='00000000-0000-0000-0000-000000000014' AND product_id='00000000-0000-0000-0000-000000009801';
 UPDATE inventory.stock_values SET value=value-200 WHERE company_id=core.current_company() AND stock_balance_id=b;
 SELECT sum(value) INTO v FROM inventory.stock_batches WHERE stock_balance_id=b;
 IF v<>50 OR EXISTS(SELECT 1 FROM inventory.stock_batches WHERE stock_balance_id=b AND value<0) THEN RAISE EXCEPTION 'Negative variance still overdraws a FIFO layer';END IF;
 UPDATE inventory.stock_values SET value=0 WHERE company_id=core.current_company() AND stock_balance_id=b;
 IF EXISTS(SELECT 1 FROM inventory.stock_batches WHERE stock_balance_id=b AND value<>0) THEN RAISE EXCEPTION 'Zero pool leaves residual cents';END IF;
END $$;
ROLLBACK TO SAVEPOINT before_variance;
SAVEPOINT before_transit;
DO $$ DECLARE p uuid:='00000000-0000-0000-0000-000000009801';w uuid:='00000000-0000-0000-0000-000000000014';w2 uuid;shipment uuid;line uuid;event uuid;cost numeric;BEGIN
 SELECT id INTO w2 FROM catalog.warehouses WHERE company_id=core.current_company() AND kind='SELLABLE' AND active AND id<>w ORDER BY id LIMIT 1;
 shipment:=inventory.dispatch_transit(w,w2,'Synthetic FIFO transit','Synthetic FIFO split receipt and return',jsonb_build_array(jsonb_build_object('productId',p,'quantity',6)));
 SELECT id,inventory.transit_transfer_lines.cost INTO line,cost FROM inventory.transit_transfer_lines WHERE company_id=core.current_company() AND transfer_id=shipment;
 IF cost<>70 THEN RAISE EXCEPTION 'Transit did not consume 5*10 + 1*20 FIFO cost';END IF;
 event:=inventory.post_transit_event(shipment,'RECEIPT','Synthetic partial receipt','Synthetic partial transit receipt',jsonb_build_array(jsonb_build_object('transferLineId',line,'quantity',3)));
 event:=inventory.post_transit_event(shipment,'RETURN','Synthetic transit return','Synthetic remaining transit return',jsonb_build_array(jsonb_build_object('transferLineId',line,'quantity',3)));
 IF EXISTS(SELECT 1 FROM accounting.reconciliation_checks() WHERE expected<>actual) THEN RAISE EXCEPTION 'FIFO transit broke ledger reconciliation';END IF;
 IF (SELECT sum(value) FROM inventory.stock_batches sb JOIN inventory.stock_balances b ON b.company_id=sb.company_id AND b.id=sb.stock_balance_id WHERE b.company_id=core.current_company() AND b.product_id=p)<>250 THEN RAISE EXCEPTION 'FIFO transit lost inventory value';END IF;
END $$;
ROLLBACK TO SAVEPOINT before_transit;
DO $$ DECLARE q uuid;q2 uuid;o uuid;customer uuid;party uuid;job jsonb;job2 jsonb;view jsonb;replay jsonb;s jsonb;link text:=repeat('a',64);n int;BEGIN
 SELECT x.id,x.customer_id INTO q,customer FROM sales.quotes x WHERE company_id=core.current_company() AND status='DRAFT' AND platform.document_visible(x.id) ORDER BY x.id LIMIT 1;
 SELECT party_id INTO party FROM crm.customers WHERE company_id=core.current_company() AND id=customer;
 INSERT INTO crm.contacts(company_id,party_id,name,email,is_accounting,created_by) VALUES(core.current_company(),party,'Synthetic accounting','accounts@example.invalid',true,core.current_actor());
 UPDATE crm.contacts SET email='accounts@example.invalid',is_accounting=true,active=true WHERE company_id=core.current_company() AND party_id=party;
 INSERT INTO sales.dispatch_settings(company_id,enabled,mail_from,notification_email,portal_origin,timezone) VALUES(core.current_company(),true,'sender@example.invalid','staff@example.invalid','https://portal.example.invalid','Australia/Melbourne');
 UPDATE sales.quotes SET status='SUBMITTED' WHERE company_id=core.current_company() AND id=q;UPDATE platform.documents SET state='CONFIRMED' WHERE company_id=core.current_company() AND id=q;
 s:=sales.set_dispatch_schedule(q,1,current_date-1,false,false,'Synthetic overdue dispatch');
 job:=sales.claim_dispatch_mail(link);IF job IS NULL THEN RAISE EXCEPTION 'Follow-up not queued';END IF;
 IF sales.finish_dispatch_mail((job->>'id')::uuid,gen_random_uuid(),'ACCEPTED',NULL,'fake') THEN RAISE EXCEPTION 'Unfenced completion accepted';END IF;
 PERFORM sales.finish_dispatch_mail((job->>'id')::uuid,(job->>'lease')::uuid,'RETRY','synthetic_429',NULL);
 IF EXISTS(SELECT 1 FROM sales.dispatch_cycles WHERE id=(job->>'id')::uuid AND expires_on IS NOT NULL) THEN RAISE EXCEPTION 'Failed delivery started quote expiry';END IF;
 UPDATE sales.dispatch_cycles SET available_at=now()-interval '1 second' WHERE id=(job->>'id')::uuid;
 job2:=sales.claim_dispatch_mail(repeat('b',64));IF job2->>'id' IS DISTINCT FROM job->>'id' THEN RAISE EXCEPTION 'Retry changed idempotency identity';END IF;
 PERFORM sales.finish_dispatch_mail((job2->>'id')::uuid,(job2->>'lease')::uuid,'ACCEPTED',NULL,'synthetic-provider-1');
 BEGIN PERFORM portal.dispatch_link(link,'https://wrong.example.invalid');RAISE EXCEPTION 'Wrong origin accepted';EXCEPTION WHEN SQLSTATE 'HT404' THEN NULL;END;
 view:=portal.dispatch_link(link,'https://portal.example.invalid');IF view->>'documentNumber' IS NULL OR view ? 'recipient' OR view ? 'customerId' THEN RAISE EXCEPTION 'Public view incorrect or leaks identity';END IF;
 BEGIN PERFORM portal.dispatch_link(link,'https://portal.example.invalid',(now() AT TIME ZONE 'Australia/Melbourne')::date,'Synthetic same-day rejection',true);RAISE EXCEPTION 'Same-day public change accepted';EXCEPTION WHEN SQLSTATE 'HI422' THEN NULL;END;
 view:=portal.dispatch_link(link,'https://portal.example.invalid',current_date+3,'Synthetic customer date change',true);
 replay:=portal.dispatch_link(link,'https://portal.example.invalid',current_date+3,'Synthetic customer date change',true);
 IF replay<>view THEN RAISE EXCEPTION 'Exact public replay changed response';END IF;
 BEGIN PERFORM portal.dispatch_link(link,'https://portal.example.invalid',current_date+4,'Changed repeat request',true);RAISE EXCEPTION 'Used link mutation accepted';EXCEPTION WHEN SQLSTATE 'HI409' THEN NULL;END;
 job:=sales.claim_dispatch_mail(repeat('c',64));IF job IS NULL OR job->'payload'->>'to' IS NULL THEN RAISE EXCEPTION 'Management notification not queued';END IF;
 PERFORM sales.finish_dispatch_mail((job->>'id')::uuid,(job->>'lease')::uuid,'ACCEPTED',NULL,'synthetic-notice');
 SELECT x.id INTO q2 FROM sales.quotes x WHERE company_id=core.current_company() AND status='DRAFT' AND id<>q AND platform.document_visible(x.id) ORDER BY x.id LIMIT 1;
 IF q2 IS NULL THEN RAISE EXCEPTION 'Second synthetic quote missing';END IF;
 UPDATE sales.quotes SET customer_id=customer,status='SUBMITTED' WHERE company_id=core.current_company() AND id=q2;UPDATE platform.documents SET state='CONFIRMED' WHERE company_id=core.current_company() AND id=q2;
 PERFORM sales.set_dispatch_schedule(q2,1,current_date-1,false,false,'Synthetic expiry case');
 job:=sales.claim_dispatch_mail(repeat('d',64));PERFORM sales.finish_dispatch_mail((job->>'id')::uuid,(job->>'lease')::uuid,'ACCEPTED',NULL,'synthetic-provider-2');
 UPDATE sales.dispatch_cycles SET expires_on=current_date-1 WHERE company_id=core.current_company() AND document_id=q2;
 IF NOT sales.dispatch_deadline_expired(q2) OR NOT sales.quote_conversion_expired(q2) THEN RAISE EXCEPTION 'Conversion accepts follow-up-expired quote';END IF;
 n:=sales.expire_dispatch_quotes();IF n<>1 OR NOT EXISTS(SELECT 1 FROM sales.dispatch_schedules WHERE document_id=q2 AND expired_at IS NOT NULL) THEN RAISE EXCEPTION 'Confirmed overdue quote not expired';END IF;
 -- Lease recovery must preserve an uncertain outcome, without automatic resend.
 INSERT INTO sales.dispatch_cycles(company_id,document_id,kind,recipient,payload,state,lease,lease_until) VALUES(core.current_company(),q2,'NOTIFICATION','staff@example.invalid','{}','PROCESSING',gen_random_uuid(),now()-interval '1 minute');
 PERFORM sales.claim_dispatch_mail(repeat('e',64));
 IF NOT EXISTS(SELECT 1 FROM sales.dispatch_cycles WHERE document_id=q2 AND state='UNKNOWN' AND last_error='lease_expired') THEN RAISE EXCEPTION 'Expired mail lease was silently retried';END IF;
 PERFORM sales.set_dispatch_schedule(q,3,current_date-1,false,false,'Synthetic recipient change case');
 job:=sales.claim_dispatch_mail(repeat('f',64));
 IF sales.load_dispatch_mail((job->>'id')::uuid,(job->>'lease')::uuid) IS NULL THEN RAISE EXCEPTION 'Valid follow-up unavailable before send';END IF;
 UPDATE crm.contacts SET email='changed@example.invalid' WHERE company_id=core.current_company() AND party_id=party AND is_accounting;
 IF sales.load_dispatch_mail((job->>'id')::uuid,(job->>'lease')::uuid) IS NOT NULL THEN RAISE EXCEPTION 'Changed follow-up recipient reached send';END IF;
 IF NOT EXISTS(SELECT 1 FROM sales.dispatch_cycles WHERE id=(job->>'id')::uuid AND state='FAILED' AND last_error='source_recipient_or_configuration_changed') THEN RAISE EXCEPTION 'Recipient guard did not persist failure';END IF;
 INSERT INTO sales.dispatch_cycles(company_id,document_id,kind,recipient,payload,state,available_at,first_attempt_at,attempts) VALUES(core.current_company(),q,'NOTIFICATION','staff@example.invalid',jsonb_build_object('from','sender@example.invalid','to',jsonb_build_array('staff@example.invalid'),'text','Synthetic expired retry window'),'RETRY',now()-interval '1 minute',now()-interval '24 hours',1);
 PERFORM sales.claim_dispatch_mail(repeat('1',64));
 IF NOT EXISTS(SELECT 1 FROM sales.dispatch_cycles WHERE company_id=core.current_company() AND document_id=q AND state='UNKNOWN' AND last_error='idempotency_window_elapsed') THEN RAISE EXCEPTION 'Expired retry window allowed another delivery';END IF;
 IF has_function_privilege('htt_app' ,'sales.claim_dispatch_mail(text)','EXECUTE') OR has_table_privilege('htt_portal','sales.dispatch_cycles','SELECT') OR has_function_privilege('htt_portal','inventory.submit_return_request(uuid,uuid,text,jsonb,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Role separation failed';END IF;
END $$;
ROLLBACK;
